const token = $env.HOME_ASSISTANT_API_TOKEN;
if (!token) throw new Error('HOME_ASSISTANT_API_TOKEN is not configured');

const entities = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8123/api/states',
  headers: {Authorization: `Bearer ${token}`},
  json: true,
});

const usefulDomains = new Set(['climate', 'cover', 'fan', 'light', 'lock', 'media_player', 'switch', 'vacuum']);
const current = {};
for (const entity of entities) {
  const domain = entity.entity_id.split('.')[0];
  if (entity.state === 'unavailable' && usefulDomains.has(domain)) current[`unavailable:${entity.entity_id}`] = 'unavailable';

  const battery = entity.attributes?.device_class === 'battery' ? Number(entity.state) : NaN;
  if (Number.isFinite(battery) && battery < 20) current[`battery:${entity.entity_id}`] = `${battery}%`;

  const temperature = entity.attributes?.device_class === 'temperature' ? Number(entity.state) : NaN;
  if (
    Number.isFinite(temperature) &&
    !/battery|car|vehicle|target/i.test(entity.entity_id) &&
    (temperature < 5 || temperature > 32)
  ) {
    current[`temperature:${entity.entity_id}`] = `${temperature} ${entity.attributes.unit_of_measurement ?? '°C'}`;
  }
}

const state = $getWorkflowStaticData('global');
if (!state.alerts) {
  state.alerts = current;
  return [];
}

const changes = [];
for (const [key, value] of Object.entries(current)) {
  if (state.alerts[key] !== value) changes.push({key, value, status: 'alert'});
}
for (const [key, value] of Object.entries(state.alerts)) {
  if (!(key in current)) changes.push({key, value, status: 'recovered'});
}
if (!changes.length) return [];

const esc = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

const rows = changes
  .map(({key, value, status}) => {
    const [kind, entity] = key.split(':');
    const colour = status === 'alert' ? '#eb6f92' : '#9ccfd8';
    return `<tr><td style="padding:9px 0;border-bottom:1px solid #393552;color:#e0def4;">${esc(entity)}<br><span style="color:${colour};">[${status.toUpperCase()}] ${esc(kind)} ${esc(value)}</span></td></tr>`;
  })
  .join('');
const html = `<html><body style="margin:0;padding:24px;background:#232136;"><table role="presentation" width="100%" style="max-width:600px;margin:auto;background:#2a273f;border:1px solid #393552;padding:24px;font-family:Verdana,sans-serif;"><tr><td style="color:#c4a7e7;font:700 20px 'Courier New',monospace;">HOME ANOMALIES</td></tr>${rows}</table></body></html>`;
return [{json: {subject: `[Home] ${changes.length} anomaly change${changes.length === 1 ? '' : 's'}`, html, nextState: current, changes}}];

const nextState = $('Check home anomalies').first().json.nextState;
const state = $getWorkflowStaticData('global');
state.alerts = nextState;
return $input.all();

// One alert per entity, and recoveries are sent as resolutions rather than as
// fresh notifications -- the spine drops a resolution for something it never
// alerted on, so this needs no memory of what it sent.
const { changes = [] } = $input.first().json;
if (changes.length === 0) return [];

return changes.map((change) => ({
  json: {
    source: "home-assistant",
    severity: "warning",
    title: String(change.key),
    message: change.status === "recovered"
      ? "Back to normal."
      : `Now ${change.value}.`,
    fingerprint: `home-assistant:${change.key}`,
    resolved: change.status === "recovered",
  },
}));
